// Changes to a text, as a list of replaced ranges. Positions are byte offsets, or lines and columns that convert to them.
#pragma once
#include <cstddef>
#include <string>
#include <vector>

namespace blitz::tools {
	struct edit {
		size_t      begin = 0; // Byte offset of the first replaced byte
		size_t      end   = 0; // Byte offset behind the last replaced byte (begin == end inserts)
		std::string replacement;
	};

	/** The byte offset of a position in the text. Lines and columns count from 1, columns in bytes. A position behind the
	 * end of a line or of the text is clamped to it.
	 */
	size_t offset_of(std::string const& text, size_t line, size_t column);

	/** An edit from positions, such as the ones the compiler reports.
	 */
	edit make_edit(std::string const& text, size_t begin_line, size_t begin_column, size_t end_line, size_t end_column, std::string replacement);

	/** Whether the edits can all be applied: They are inside the text and none overlaps another. Edits that only touch
	 * (one ends where the next begins) are fine, and so are inserts at the same offset (they apply in the given order).
	 * Returns false and describes the first problem in 'error'.
	 */
	bool check_edits(std::string const& text, std::vector<edit> const& edits, std::string& error);

	/** Apply the edits, which don't have to be sorted. Throws std::runtime_error if check_edits fails.
	 */
	std::string apply_edits(std::string const& text, std::vector<edit> edits);
} // namespace blitz::tools
